    Hb = [[0]*4 for _ in range(4)]
    Ho = [[0]*4 for _ in range(4)]
    for r in range(4):
        for s in range(4):
            if (r + s) % 2 == 1:
                Ho[r][s] = 1
            else:
                g = r + (s // 2) + (r + s) // 2
                Hb[r][s] = 1 if g % 2 == 0 else 0

    def make(tab):
        T = sum(sum(row) for row in tab)
        R = [sum(tab[r][s] for r in range(4)) for s in range(4)]
        Cc = [sum(tab[r][s] for s in range(4)) for r in range(4)]

        def Q(x, y):
            qx, rx = divmod(x, 4)
            qy, ry = divmod(y, 4)
