            res += qx * sum(R[s] for s in range(ry))
            res += qy * sum(Cc[r] for r in range(rx))
            res += sum(tab[r][s] for r in range(rx) for s in range(ry))
            return res

        def rect(a, b, c, d):
            return Q(c, d) - Q(a, d) - Q(c, b) + Q(a, b)

        return rect

